window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5c37527c55b50d06"]={"versions": [{"id": "FIG-5c37527c55b50d06", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (M2-Metamodellauszug der AUTOSAR Adaptive Platform).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der Vererbungshierarchie für Port-Interfaces im Kontext des Intrusion Detection System Manager (IdsM).\n</li><li><strong>Architektur-Kontext:</strong> Definition der spezialisierten Schnittstellentypen, über die Adaptive Applications oder Plattformdienste sicherheitsrelevante Ereignisse an den IdsM melden (<code>SecurityEventReportInterface</code>) sowie Zeitstempel (<code>IdsmTimestampProviderInterface</code>) oder Kontextdaten (<code>IdsmContextProviderInterface</code>) für forensische Sicherheitsanalysen bereitstellen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code> (Abstrakte Basisklasse):</strong>\n<ul class=\"fig-list\"><li><em>Stereotypen:</em> <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>.\n</li><li><em>Funktion:</em> Grundlegendes Metamodellelement zur Modellierung von typisierten Port-Schnittstellen. Durch <code>«ARElement»</code> ist es als eigenständiges Artefakt in einem <code>ARPackage</code> deklarierbar.\n</li></ul>\n</li><li><strong><code>IdsmAbstractPortInterface</code> (Abstrakte Basisklasse):</strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt via Generalisierung von <code>PortInterface</code>.\n</li><li><em>Funktion:</em> Gemeinsamer abstrakter Basistyp für alle IdsM-spezifischen Port-Schnittstellen im Manifest-Metamodell.\n</li></ul>\n</li><li><strong>Spezialisierte Schnittstellen (Konkrete Metaklassen):</strong>\n<ul class=\"fig-list\"><li><strong><code>IdsmTimestampProviderInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports, über die der IdsM Zeitstempel abfragt, um Sicherheitsereignisse manipulationssicher zu synchronisieren/datieren.\n</li><li><strong><code>IdsmContextProviderInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports, über welche der IdsM erweiterte Laufzeit- und Umgebungskontexte (z. B. Fehlerspeicher-Zustand, Netzwerkstatus) zur Anreicherung gemeldeter Events anfordert.\n</li><li><strong><code>SecurityEventReportInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports von On-Board-Sensoren (SWCs, OS, Netzwerk-Stacks), um Security Events direkt an den IdsM zu übermitteln.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Metamodell-Klassendiagramm handelt, ist kein Sequenzfluss direkt dargestellt. Aus den Schnittstellen resultiert folgendes Laufzeitverhalten:</em></p>\n<ol class=\"fig-list\"><li><strong>Event-Triggering (asynchron/synchron):</strong> Eine Komponente detektiert eine Sicherheitsanomalie (z. B. ungültige CAN-/Ethernet-Frames, Authentifizierungsfehler) und triggert über einen <code>RPort</code> mit <code>SecurityEventReportInterface</code> die Meldung an den IdsM (<code>PPort</code>).\n</li><li><strong>Kontext- und Zeitstempel-Abfrage:</strong>\n<ul class=\"fig-list\"><li>Falls konfiguriert, ruft der IdsM synchron oder asynchron über ein <code>IdsmTimestampProviderInterface</code> einen qualifizierten Zeitstempel ab.\n</li><li>Der IdsM pollt bzw. ruft Callback-Methoden über ein <code>IdsmContextProviderInterface</code> auf, um systemspezifische Zustandsdaten vor der Persistierung/Weiterleitung zu erfassen.\n</li></ul>\n</li><li><strong>Filterung &amp; Aggregation:</strong> Der IdsM filtert (Thresholding/Sampling), aggregiert das Event und leitet es an das Security Event Memory (SEM) oder das Backend weiter.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Modellierung im ARXML-Manifest:</strong>\n<ul class=\"fig-list\"><li>Entwickler dürfen <code>IdsmAbstractPortInterface</code> nicht direkt instanziieren (Abstraktionsgrad im Metamodell). Es müssen die konkreten Subtypen (<code>SecurityEventReportInterface</code>, <code>IdsmContextProviderInterface</code>, <code>IdsmTimestampProviderInterface</code>) verwendet werden.\n</li><li>Diese Interfaces werden als Typen für <code>RPortPrototype</code> bzw. <code>PPortPrototype</code> in <code>AdaptiveApplicationSwComponentType</code> referenziert.\n</li></ul>\n</li><li><strong>API- und Stack-Generierung:</strong>\n<ul class=\"fig-list\"><li>Generatoren erzeugen aus diesen Definitionen die C++-Klassen/Proxy-Skeleton-Architektur bzw. die AUTOSAR Runtime for Adaptive Applications (ara::core / ara::idsm).\n</li></ul>\n</li><li><strong>Konfigurationsbindungen:</strong>\n<ul class=\"fig-list\"><li>Jedem <code>SecurityEventReportInterface</code> müssen die entsprechenden Security Event IDs (SEv-Definitionen) über das System- bzw. Applikationsmanifest zugeordnet werden.\n</li><li>Anbieter von Kontext oder Zeitstempeln müssen deterministische Antwortzeiten garantieren, um Latenzen in der IdsM-Pipeline zu vermeiden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-91e1b051981710d0", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (M2-Metamodellauszug der AUTOSAR Adaptive Platform).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der Vererbungshierarchie für Port-Interfaces im Kontext des Intrusion Detection System Manager (IdsM).\n</li><li><strong>Architektur-Kontext:</strong> Definition der spezialisierten Schnittstellentypen, über die Adaptive Applications oder Plattformdienste sicherheitsrelevante Ereignisse an den IdsM melden (<code>SecurityEventReportInterface</code>), Zeitstempel (<code>IdsmTimestampProviderInterface</code>) oder Kontextdaten (<code>IdsmContextProviderInterface</code>) bereitstellen, den Reporting-Modus des IdsM konfigurieren (<code>IdsmReportingModeProviderInterface</code>) sowie qualifizierte Sicherheitsereignisse vom IdsM empfangen (<code>IdsmQualifiedEventReceiverInterface</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code> (Abstrakte Basisklasse):</strong>\n<ul class=\"fig-list\"><li><em>Stereotypen:</em> <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>.\n</li><li><em>Funktion:</em> Grundlegendes Metamodellelement zur Modellierung von typisierten Port-Schnittstellen. Durch <code>«ARElement»</code> ist es als eigenständiges Artefakt in einem <code>ARPackage</code> deklarierbar.\n</li></ul>\n</li><li><strong><code>IdsmAbstractPortInterface</code> (Abstrakte Basisklasse):</strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt via Generalisierung von <code>PortInterface</code>.\n</li><li><em>Funktion:</em> Gemeinsamer abstrakter Basistyp für alle IdsM-spezifischen Port-Schnittstellen im Manifest-Metamodell.\n</li></ul>\n</li><li><strong>Spezialisierte Schnittstellen (Konkrete Metaklassen):</strong>\n<ul class=\"fig-list\"><li><strong><code>IdsmQualifiedEventReceiverInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports für Empfängerkomponenten, die vom IdsM qualifizierte und aggregierte Security Events zur Weiterleitung oder Persistierung entgegennehmen.\n</li><li><strong><code>IdsmReportingModeProviderInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports, über die der Reporting-Modus des IdsM bereitgestellt oder gesteuert wird (z. B. Umschaltung des Detaillierungsgrads oder Aktivierungsstatus der Berichterstattung).\n</li><li><strong><code>SecurityEventReportInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports von On-Board-Sensoren (SWCs, OS, Netzwerk-Stacks), um Security Events direkt an den IdsM zu übermitteln.\n</li><li><strong><code>IdsmTimestampProviderInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports, über die der IdsM Zeitstempel abfragt, um Sicherheitsereignisse manipulationssicher zu synchronisieren/datieren.\n</li><li><strong><code>IdsmContextProviderInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports, über welche der IdsM erweiterte Laufzeit- und Umgebungskontexte (z. B. Fehlerspeicher-Zustand, Netzwerkstatus) zur Anreicherung gemeldeter Events anfordert.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Metamodell-Klassendiagramm handelt, ist kein Sequenzfluss direkt dargestellt. Aus den Schnittstellen resultiert folgendes Laufzeitverhalten:</em></p>\n<ol class=\"fig-list\"><li><strong>Reporting-Modus-Steuerung:</strong> Über ein <code>IdsmReportingModeProviderInterface</code> erhält der IdsM Vorgaben zum aktiven Reporting-Modus, wodurch das Weiterleitungs- und Filterverhalten zur Laufzeit beeinflusst wird.\n</li><li><strong>Event-Triggering (asynchron/synchron):</strong> Eine Sensor-Komponente detektiert eine Sicherheitsanomalie (z. B. ungültige CAN-/Ethernet-Frames, Authentifizierungsfehler) und meldet das Event über einen <code>RPort</code> mit <code>SecurityEventReportInterface</code> an den IdsM (<code>PPort</code>).\n</li><li><strong>Kontext- und Zeitstempel-Abfrage:</strong>\n<ul class=\"fig-list\"><li>Falls konfiguriert, ruft der IdsM synchron oder asynchron über ein <code>IdsmTimestampProviderInterface</code> einen qualifizierten Zeitstempel ab.\n</li><li>Der IdsM pollt bzw. ruft Callback-Methoden über ein <code>IdsmContextProviderInterface</code> auf, um systemspezifische Zustandsdaten vor der Persistierung/Weiterleitung zu erfassen.\n</li></ul>\n</li><li><strong>Qualifizierung &amp; Weitergabe:</strong> Der IdsM filtert und aggregiert das Ereignis zu einem qualifizierten Security Event und gibt dieses über ein <code>IdsmQualifiedEventReceiverInterface</code> an registrierte Empfänger weiter.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Modellierung im ARXML-Manifest:</strong>\n<ul class=\"fig-list\"><li>Entwickler dürfen <code>IdsmAbstractPortInterface</code> nicht direkt instanziieren (Abstraktionsgrad im Metamodell). Es müssen die konkreten Subtypen (<code>SecurityEventReportInterface</code>, <code>IdsmContextProviderInterface</code>, <code>IdsmTimestampProviderInterface</code>, <code>IdsmReportingModeProviderInterface</code>, <code>IdsmQualifiedEventReceiverInterface</code>) verwendet werden.\n</li><li>Diese Interfaces werden als Typen für <code>RPortPrototype</code> bzw. <code>PPortPrototype</code> in <code>AdaptiveApplicationSwComponentType</code> referenziert, um IdsM-Kommunikationsendpunkte zu modellieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-46929807268189af", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (M2-Metamodellauszug der AUTOSAR Adaptive Platform).\n</li><li><strong>Technischer Zweck:</strong> Modellierung der Vererbungshierarchie für Port-Interfaces im Kontext des Intrusion Detection System Manager (IdsM).\n</li><li><strong>Architektur-Kontext:</strong> Definition der spezialisierten Schnittstellentypen, über die Adaptive Applications oder Plattformdienste sicherheitsrelevante Ereignisse an den IdsM melden (<code>SecurityEventReportInterface</code>), Zeitstempel (<code>IdsmTimestampProviderInterface</code>) oder Kontextdaten (<code>IdsmContextProviderInterface</code>) bereitstellen, den Reporting-Modus des IdsM konfigurieren (<code>IdsmReportingModeProviderInterface</code>) sowie qualifizierte Sicherheitsereignisse vom IdsM empfangen (<code>IdsmQualifiedEventReceiverInterface</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>PortInterface</code> (Abstrakte Basisklasse):</strong>\n<ul class=\"fig-list\"><li><em>Stereotypen:</em> <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>.\n</li><li><em>Funktion:</em> Grundlegendes Metamodellelement zur Modellierung von typisierten Port-Schnittstellen. Durch <code>«ARElement»</code> ist es als eigenständiges Artefakt in einem <code>ARPackage</code> deklarierbar.\n</li></ul>\n</li><li><strong><code>IdsmAbstractPortInterface</code> (Abstrakte Basisklasse):</strong>\n<ul class=\"fig-list\"><li><em>Spezialisierung:</em> Erbt via Generalisierung von <code>PortInterface</code>.\n</li><li><em>Funktion:</em> Gemeinsamer abstrakter Basistyp für alle IdsM-spezifischen Port-Schnittstellen im Manifest-Metamodell.\n</li></ul>\n</li><li><strong>Spezialisierte Schnittstellen (Konkrete Metaklassen):</strong>\n<ul class=\"fig-list\"><li><strong><code>IdsmQualifiedEventReceiverInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports für Empfängerkomponenten, die vom IdsM qualifizierte und aggregierte Security Events zur Weiterleitung oder Persistierung entgegennehmen.\n</li><li><strong><code>IdsmReportingModeProviderInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports, über die der Reporting-Modus des IdsM bereitgestellt oder gesteuert wird (z. B. Umschaltung des Detaillierungsgrads oder Aktivierungsstatus der Berichterstattung).\n</li><li><strong><code>SecurityEventReportInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports von On-Board-Sensoren (SWCs, OS, Netzwerk-Stacks), um Security Events direkt an den IdsM zu übermitteln.\n</li><li><strong><code>IdsmTimestampProviderInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports, über die der IdsM Zeitstempel abfragt, um Sicherheitsereignisse manipulationssicher zu synchronisieren/datieren.\n</li><li><strong><code>IdsmContextProviderInterface</code>:</strong> Spezialisiert <code>IdsmAbstractPortInterface</code>. Typisiert Ports, über welche der IdsM erweiterte Laufzeit- und Umgebungskontexte (z. B. Fehlerspeicher-Zustand, Netzwerkstatus) zur Anreicherung gemeldeter Events anfordert.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Metamodell-Klassendiagramm handelt, ist kein Sequenzfluss direkt dargestellt. Aus den Schnittstellen resultiert folgendes Laufzeitverhalten:</em></p>\n<ol class=\"fig-list\"><li><strong>Reporting-Modus-Steuerung:</strong> Über ein <code>IdsmReportingModeProviderInterface</code> erhält der IdsM Vorgaben zum aktiven Reporting-Modus, wodurch das Weiterleitungs- und Filterverhalten zur Laufzeit beeinflusst wird.\n</li><li><strong>Event-Triggering (asynchron/synchron):</strong> Eine Sensor-Komponente detektiert eine Sicherheitsanomalie (z. B. ungültige CAN-/Ethernet-Frames, Authentifizierungsfehler) und meldet das Event über einen <code>RPort</code> mit <code>SecurityEventReportInterface</code> an den IdsM (<code>PPort</code>).\n</li><li><strong>Kontext- und Zeitstempel-Abfrage:</strong>\n<ul class=\"fig-list\"><li>Falls konfiguriert, ruft der IdsM synchron oder asynchron über ein <code>IdsmTimestampProviderInterface</code> einen qualifizierten Zeitstempel ab.\n</li><li>Der IdsM pollt bzw. ruft Callback-Methoden über ein <code>IdsmContextProviderInterface</code> auf, um systemspezifische Zustandsdaten vor der Persistierung/Weiterleitung zu erfassen.\n</li></ul>\n</li><li><strong>Qualifizierung &amp; Weitergabe:</strong> Der IdsM filtert und aggregiert das Ereignis zu einem qualifizierten Security Event und gibt dieses über ein <code>IdsmQualifiedEventReceiverInterface</code> an registrierte Empfänger weiter.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Modellierung im ARXML-Manifest:</strong>\n<ul class=\"fig-list\"><li>Entwickler dürfen <code>IdsmAbstractPortInterface</code> nicht direkt instanziieren (Abstraktionsgrad im Metamodell). Es müssen die konkreten Subtypen (<code>SecurityEventReportInterface</code>, <code>IdsmContextProviderInterface</code>, <code>IdsmTimestampProviderInterface</code>, <code>IdsmReportingModeProviderInterface</code>, <code>IdsmQualifiedEventReceiverInterface</code>) verwendet werden.\n</li><li>Diese Interfaces werden als Typen für <code>RPortPrototype</code> bzw. <code>PPortPrototype</code> in <code>AdaptiveApplicationSwComponentType</code> referenziert, um IdsM-Kommunikationsendpunkte zu modellieren.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-5c37527c55b50d06", "to": "FIG-91e1b051981710d0", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>IdsmQualifiedEventReceiverInterface</code>: Neue Metaklasse als Spezialisierung von <code>IdsmAbstractPortInterface</code> hinzugefügt.\n</li><li><code>IdsmReportingModeProviderInterface</code>: Neue Metaklasse als Spezialisierung von <code>IdsmAbstractPortInterface</code> hinzugefügt.\n</li><li>Generalisierungshierarchie / Layout: Anordnung der Spezialisierungen von horizontal unterhalb der Basisklasse zu einer vertikalen Kaskade rechts neben <code>IdsmAbstractPortInterface</code> umstrukturiert.\n</li></ul>"}, {"from": "FIG-91e1b051981710d0", "to": "FIG-46929807268189af", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
